/**
 * Worker entry point: wraps the worker generated by @sveltejs/adapter-cloudflare.
 *
 * The adapter's `_headers` marks every `/_app/immutable/*` response as
 * `public, immutable, max-age=31536000`, including 404s. During a deploy, a page from
 * the new version can request a chunk from an edge that is still serving the old one;
 * that 404 is then cached by the browser for a year and the page never hydrates.
 * Missing immutable files are therefore sent with `no-store`, so the next load retries.
 *
 * The adapter writes its worker to the `main` of `wrangler.adapter.jsonc`, which is why
 * this file can be the `main` of `wrangler.jsonc` without being overwritten.
 */
import sveltekit from './.svelte-kit/cloudflare/_worker.js';

const IMMUTABLE_PATH = '/_app/immutable/';

export default {
	/**
	 * @param {Request} request
	 * @param {unknown} env
	 * @param {unknown} ctx
	 */
	async fetch(request, env, ctx) {
		const response = await sveltekit.fetch(request, env, ctx);

		if (response.status < 400 || !new URL(request.url).pathname.startsWith(IMMUTABLE_PATH)) {
			return response;
		}

		const uncached = new Response(response.body, response);
		uncached.headers.set('Cache-Control', 'no-store');
		return uncached;
	}
};
